'use strict';

const fs = require('fs');

const SIZE = 1000002;
const s = new Uint8Array(SIZE);
const p = new Int32Array(SIZE);
let np = 0;
let min = 2147483647;

function sieve() {
  for (let i = 2; i < SIZE; i++) {
    if (s[i] === 0) {
      p[np++] = i;

      for (let j = 2; i * j < SIZE; j++) {
        s[i * j] = 1;
      }
    }
  }
}

function solve(x, l) {
  let lf = -1;
  let ox = x;

  if (x < min) {
    min = x;
  }

  if (l === 0) {
    return;
  }

  for (let i = 0; p[i] * p[i] <= x; i++) {
    if (ox % p[i] === 0) {
      lf = Math.max(lf, p[i]);
      while (ox % p[i] === 0) {
        ox /= p[i];
      }
    }
  }

  if (ox > 1 && ox !== x) {
    lf = Math.max(lf, ox);
  }

  if (lf === -1) {
    return;
  }

  if (l === 1) {
    x = x - lf + 1;
    if (x < min) {
      min = x;
    }
    return;
  }

  for (let d = x - lf + 1; d < lf * Math.floor(x / lf); d++) {
    solve(d, l - 1);
  }
}

s[0] = s[1] = 1;
sieve();

const x2 = Number(fs.readFileSync(0, 'utf8').trim());
solve(x2, 2);
process.stdout.write(String(min));

